import (
	"fmt"
	"os"

	"github.com/entireio/cli/redact"
)

func main() {
	_ = redact.String("key=REDACTED")
	for _, name := range []string{
		"GIT_CONFIG_GLOBAL",
		"GIT_CONFIG_NOSYSTEM",
		"GIT_CONFIG_SYSTEM",
		"GIT_NO_REPLACE_OBJECTS",
		"GIT_TERMINAL_PROMPT",
	} {
		if value, ok := os.LookupEnv(name); ok {
			fmt.Printf("%s=%s\n", name, value)
		}
	}
