go 1.26.2

require github.com/entireio/cli v0.0.0

replace github.com/entireio/cli => ` + filepath.ToSlash(repoRoot) + `
`
	if err := os.WriteFile(filepath.Join(tmpDir, "go.mod"), []byte(goMod), 0o644); err != nil {
