		{
			name:  "two AWS keys separated by space produce two REDACTED tokens",
			input: "key=REDACTED REDACTED",
			want:  "key=REDACTED REDACTED",
		},
		{
			name:  "adjacent AWS keys without separator merge into single REDACTED",
			input: "key=REDACTED",
			want:  "key=REDACTED",
		},
